-- | WebAssembly text format (WAT) code generator for Awsum 'Core'.
--
-- Produces human-readable WAT (S-expression syntax) used for
-- @awsum build -t wasm@ output and snapshot tests.
-- The binary @.wasm@ is generated by 'Awsum.Codegen.WASM.Assemble'.
--
-- Design:
--   * All values are @i32@ (pointers into linear memory).
--   * Strings are null-terminated bytes in linear memory (like LLVM).
--   * WASI provides I\/O: @fd_write@ for stdout, @args_get@ for CLI args.
--   * Bump allocator for dynamic memory (concat results).
--   * @funcref@ table + @call_indirect@ for higher-order functions.
module Awsum.Codegen.WASM (codegenWASM) where

import Awsum.Core
import Awsum.Syntax (Name)
import Data.Char qualified as Char
import Data.Map.Strict qualified as Map
import Data.Set qualified as Set
import Data.Text qualified as T
import Relude

-- ════════════════════════════════════════════════════════════════════════════
-- Public API
-- ════════════════════════════════════════════════════════════════════════════

-- | Produce a complete WAT module from a Core program.
codegenWASM :: CoreProgram -> Text
codegenWASM prog@(CoreProgram decls) =
  let (pool, emptyOff, heapStart) = buildStringPool prog
      valNames = Set.fromList [n | CValDef n _ <- decls]
      funNames = Set.fromList [n | CFunDef n _ _ <- decls]
      arities = Map.fromList [(n, length as) | CFunDef n as _ <- decls]
      funDefs = [n | CFunDef n _ _ <- decls]
      tableMap = Map.fromList (zip funDefs [0 :: Int ..])
      indirectArities = collectIndirectArities (CoreProgram decls) funNames
      ctx =
        WasmCtx
          { wParams = Set.empty,
            wValDefs = valNames,
            wFunDefs = funNames,
            wArities = arities,
            wStringPool = pool,
            wTableMap = tableMap,
            wIndirectArities = indirectArities,
            wLocalExprs = Map.empty,
            wConDepth = 0
          }
   in T.intercalate
        "\n"
        [ header,
          imports,
          memory,
          global heapStart,
          dataSection pool,
          table (length funDefs),
          elemSection funDefs,
          typeDecls indirectArities,
          runtimeHelpers emptyOff (usedPrims prog) (usedBuiltIns prog) (usesIntLit prog),
          T.intercalate "\n\n" (map (emitDecl ctx) decls),
          "",
          startFunc,
          ")"
        ]

-- ════════════════════════════════════════════════════════════════════════════
-- Context
-- ════════════════════════════════════════════════════════════════════════════

data WasmCtx = WasmCtx
  { wParams :: Set Text,
    wValDefs :: Set Text,
    wFunDefs :: Set Text,
    wArities :: Map Text Int,
    wStringPool :: Map Text Int,
    wTableMap :: Map Text Int,
    wIndirectArities :: Set Int,
    wLocalExprs :: Map Text Text, -- case-bound variable → inline WAT expression
    wConDepth :: Int -- nesting depth for $__con_N locals
  }

-- ════════════════════════════════════════════════════════════════════════════
-- String pool
-- ════════════════════════════════════════════════════════════════════════════

-- | Offset where string constants begin in linear memory.
scratchSize :: Int
scratchSize = 64

-- | Build a string pool with byte offsets.
--   Always includes "" for __get_arg fallback.
--   Returns (pool, empty_string_offset, heap_start).
buildStringPool :: CoreProgram -> (Map Text Int, Int, Int)
buildStringPool (CoreProgram decls) =
  let strs = ordNub $ "" : concatMap stringsInDecl decls
      offsets = scanl (\off s -> off + byteLen s + 1) scratchSize strs
      pool = Map.fromList (zip strs offsets)
      emptyOff = fromMaybe scratchSize (Map.lookup "" pool)
      heapStart = fromMaybe scratchSize $ viaNonEmpty Relude.last (zipWith (\s o -> o + byteLen s + 1) strs offsets)
   in (pool, emptyOff, heapStart)

-- | Byte length of a string. Currently all strings are ASCII,
--   so T.length == byte length. When multi-byte UTF-8 is supported,
--   this should use Data.Text.Encoding.encodeUtf8 + BS.length.
byteLen :: Text -> Int
byteLen = T.length

stringsInDecl :: CDecl -> [Text]
stringsInDecl = \case
  CFunDef _ _ body -> stringsInExpr body
  CValDef _ rhs -> stringsInExpr rhs

stringsInExpr :: CExpr -> [Text]
stringsInExpr = \case
  CString s -> [s]
  CVar _ -> []
  CIntLit _ _ -> []
  CPrim _ -> []
  CBuiltIn _ -> []
  CCon _ fields -> concatMap stringsInExpr fields
  CCase scrut alts -> stringsInExpr scrut <> concatMap (\(_, _, body) -> stringsInExpr body) alts
  CCall f xs -> stringsInExpr f <> concatMap stringsInExpr xs

-- | Collect arities used in indirect calls (CCall where callee is a param, not a known fun/prim).
collectIndirectArities :: CoreProgram -> Set Text -> Set Int
collectIndirectArities (CoreProgram decls) funNames =
  Set.fromList $ concatMap (collectInDecl funNames) decls
  where
    collectInDecl :: Set Text -> CDecl -> [Int]
    collectInDecl fns = \case
      CFunDef _ args body -> collectInExpr fns (Set.fromList args) body
      CValDef _ rhs -> collectInExpr fns Set.empty rhs

    collectInExpr :: Set Text -> Set Text -> CExpr -> [Int]
    collectInExpr fns params = \case
      CCall f xs ->
        let fromF = case f of
              CVar n | n `Set.member` params -> [length xs]
              _ -> []
            fromChildren = collectInExpr fns params f <> concatMap (collectInExpr fns params) xs
         in fromF <> fromChildren
      _ -> []

-- ════════════════════════════════════════════════════════════════════════════
-- Module sections (text)
-- ════════════════════════════════════════════════════════════════════════════

header :: Text
header =
  unlines
    [ ";; Awsum WASM codegen — WAT text format for inspection.",
      ";; Binary .wasm is generated by assembleWASM for execution.",
      "(module"
    ]

imports :: Text
imports =
  unlines
    [ "  (import \"wasi_snapshot_preview1\" \"fd_write\" (func $fd_write (param i32 i32 i32 i32) (result i32)))",
      "  (import \"wasi_snapshot_preview1\" \"args_sizes_get\" (func $args_sizes_get (param i32 i32) (result i32)))",
      "  (import \"wasi_snapshot_preview1\" \"args_get\" (func $args_get (param i32 i32) (result i32)))"
    ]

memory :: Text
memory = "  (memory (export \"memory\") 1)"

global :: Int -> Text
global heapStart = "  (global $heap (mut i32) (i32.const " <> show heapStart <> "))"

dataSection :: Map Text Int -> Text
dataSection pool
  | Map.null pool = ""
  | otherwise =
      T.intercalate "\n"
        $ map emitData (sortWith snd $ Map.toList pool)
  where
    emitData (s, off) =
      "  (data (i32.const " <> show off <> ") " <> watString s <> ")"

-- | Format a string for WAT data section (includes null terminator).
watString :: Text -> Text
watString s = "\"" <> watEscape s <> "\\00\""

-- | Escape a string for WAT syntax.
watEscape :: Text -> Text
watEscape = T.concatMap escChar
  where
    escChar c
      | c == '\\' = "\\\\"
      | c == '"' = "\\22"
      | c == '\n' = "\\0a"
      | c == '\t' = "\\09"
      | c == '\r' = "\\0d"
      | c == '\0' = "\\00"
      | Char.isPrint c = one c
      | otherwise =
          let n = Char.ord c
              hi = n `div` 16
              lo = n `mod` 16
              hexChar x
                | x < 10 = chr (Char.ord '0' + x)
                | otherwise = chr (Char.ord 'a' + x - 10)
           in "\\" <> toText [hexChar hi, hexChar lo]

table :: Int -> Text
table n
  | n == 0 = ""
  | otherwise = "  (table " <> show n <> " funcref)"

elemSection :: [Text] -> Text
elemSection fns
  | null fns = ""
  | otherwise =
      "  (elem (i32.const 0) " <> T.intercalate " " (map (\n -> "$" <> mangle n) fns) <> ")"

typeDecls :: Set Int -> Text
typeDecls arities
  | Set.null arities = ""
  | otherwise =
      T.intercalate "\n"
        $ map emitType (Set.toAscList arities)
  where
    emitType arity =
      "  (type $arity_"
        <> show arity
        <> " (func"
        <> (if arity > 0 then " (param" <> T.concat (replicate arity " i32") <> ")" else "")
        <> " (result i32)))"

-- ════════════════════════════════════════════════════════════════════════════
-- Runtime helpers
-- ════════════════════════════════════════════════════════════════════════════

-- | Emit only the runtime helpers referenced in Core. @__alloc@ /
--   @__strlen@ / @__memcpy@ / @__get_arg@ are always needed (the last
--   feeds argv into main; the rest are small infrastructure), the
--   higher-level helpers (@__concat@, @__print@, @__box_i32@,
--   @__show_i32@, @__predInt32@) are gated on usage.
runtimeHelpers :: Int -> Set Prim -> Set Name -> Bool -> Text
runtimeHelpers emptyOff prims builtIns hasIntLit =
  let lns =
        filter
          (not . T.null)
          [ rtStrlen,
            rtAlloc,
            rtMemcpy,
            if Set.member PrimConcat prims then rtConcat else "",
            if Set.member PrimPrint prims then rtPrint else "",
            if hasIntLit then rtBoxI32 else "",
            if any (`Set.member` prims) [PrimShowInt TInt32, PrimShowInt TUInt8] || any (`Set.member` builtIns) ["showInt32", "showUInt8"]
              then rtShowI32
              else "",
            if Set.member "predInt32" builtIns then rtPredI32 else "",
            rtGetArg emptyOff
          ]
   in T.intercalate "\n\n" lns

rtStrlen :: Text
rtStrlen =
  unlines
    [ "  (func $__strlen (param $s i32) (result i32)",
      "    (local $len i32)",
      "    (local.set $len (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        (br_if $break (i32.eqz (i32.load8_u (i32.add (local.get $s) (local.get $len)))))",
      "        (local.set $len (i32.add (local.get $len) (i32.const 1)))",
      "        (br $loop)))",
      "    (local.get $len))"
    ]

rtAlloc :: Text
rtAlloc =
  unlines
    [ "  (func $__alloc (param $size i32) (result i32)",
      "    (local $ptr i32)",
      "    (local.set $ptr (i32.and (i32.add (global.get $heap) (i32.const 3)) (i32.const -4)))",
      "    (global.set $heap (i32.add (local.get $ptr) (local.get $size)))",
      "    (if (i32.gt_u (global.get $heap) (i32.mul (memory.size) (i32.const 65536)))",
      "      (then (drop (memory.grow (i32.const 1)))))",
      "    (local.get $ptr))"
    ]

rtMemcpy :: Text
rtMemcpy =
  unlines
    [ "  (func $__memcpy (param $dst i32) (param $src i32) (param $len i32)",
      "    (local $i i32)",
      "    (local.set $i (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        (br_if $break (i32.ge_u (local.get $i) (local.get $len)))",
      "        (i32.store8 (i32.add (local.get $dst) (local.get $i))",
      "                    (i32.load8_u (i32.add (local.get $src) (local.get $i))))",
      "        (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "        (br $loop))))"
    ]

rtConcat :: Text
rtConcat =
  unlines
    [ "  (func $__concat (param $a i32) (param $b i32) (result i32)",
      "    (local $la i32) (local $lb i32) (local $buf i32)",
      "    (local.set $la (call $__strlen (local.get $a)))",
      "    (local.set $lb (call $__strlen (local.get $b)))",
      "    (local.set $buf (call $__alloc (i32.add (i32.add (local.get $la) (local.get $lb)) (i32.const 1))))",
      "    (call $__memcpy (local.get $buf) (local.get $a) (local.get $la))",
      "    (call $__memcpy (i32.add (local.get $buf) (local.get $la)) (local.get $b) (local.get $lb))",
      "    (i32.store8 (i32.add (local.get $buf) (i32.add (local.get $la) (local.get $lb))) (i32.const 0))",
      "    (local.get $buf))"
    ]

rtPrint :: Text
rtPrint =
  unlines
    [ "  (func $__print (param $s i32) (result i32)",
      "    (local $len i32)",
      "    (local.set $len (call $__strlen (local.get $s)))",
      "    (i32.store (i32.const 0) (local.get $s))",
      "    (i32.store (i32.const 4) (local.get $len))",
      "    (drop (call $fd_write (i32.const 1) (i32.const 0) (i32.const 1) (i32.const 8)))",
      "    (i32.const 0))"
    ]

-- | Box a 32-bit value as a heap cell; the returned pointer is the uniform
--   representation of both Int32 and UInt8 at runtime (UInt8 values 0..255
--   fit trivially in 32 bits, which avoids a second boxing variant).
rtBoxI32 :: Text
rtBoxI32 =
  unlines
    [ "  (func $__box_i32 (param $v i32) (result i32)",
      "    (local $p i32)",
      "    (local.set $p (call $__alloc (i32.const 4)))",
      "    (i32.store (local.get $p) (local.get $v))",
      "    (local.get $p))"
    ]

-- | Render a boxed integer as a decimal null-terminated string.
--
--   The input pointer holds a 32-bit value; we treat it as signed (@i32.lt_s@)
--   for the minus-sign check. UInt8 values 0..255 are always positive in the
--   signed interpretation, so the same routine renders them correctly.
--
--   Algorithm: write digits into a 16-byte scratch buffer starting at the
--   second-to-last byte and moving left. 11 digits (@-2147483648@) + null
--   terminator is the worst case, which comfortably fits.
--
--   Negation of @INT_MIN@ is a no-op in two's complement, but since we use
--   @i32.div_u@ / @i32.rem_u@ on the magnitude, the unsigned reading of
--   @0x80000000@ is @2147483648@ — the correct magnitude.
rtShowI32 :: Text
rtShowI32 =
  unlines
    [ "  (func $__show_i32 (param $p i32) (result i32)",
      "    (local $v i32) (local $buf i32) (local $pos i32) (local $neg i32) (local $mag i32) (local $digit i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (local.set $buf (call $__alloc (i32.const 16)))",
      "    (i32.store8 (i32.add (local.get $buf) (i32.const 15)) (i32.const 0))",
      "    (local.set $pos (i32.const 14))",
      "    (if (i32.lt_s (local.get $v) (i32.const 0))",
      "      (then",
      "        (local.set $neg (i32.const 1))",
      "        (local.set $mag (i32.sub (i32.const 0) (local.get $v))))",
      "      (else",
      "        (local.set $neg (i32.const 0))",
      "        (local.set $mag (local.get $v))))",
      "    (if (i32.eqz (local.get $mag))",
      "      (then",
      "        (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.const 48))",
      "        (local.set $pos (i32.sub (local.get $pos) (i32.const 1))))",
      "      (else",
      "        (block $done",
      "          (loop $loop",
      "            (br_if $done (i32.eqz (local.get $mag)))",
      "            (local.set $digit (i32.rem_u (local.get $mag) (i32.const 10)))",
      "            (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.add (local.get $digit) (i32.const 48)))",
      "            (local.set $pos (i32.sub (local.get $pos) (i32.const 1)))",
      "            (local.set $mag (i32.div_u (local.get $mag) (i32.const 10)))",
      "            (br $loop)))))",
      "    (if (local.get $neg)",
      "      (then",
      "        (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.const 45))",
      "        (local.set $pos (i32.sub (local.get $pos) (i32.const 1)))))",
      "    (i32.add (local.get $buf) (i32.add (local.get $pos) (i32.const 1))))"
    ]

-- | predInt32: Int32 -> Either UnderflowError Int32.
--   Containers follow the uniform WASM layout [i32 tag at offset 0,
--   i32 fields at offsets 4, 8, ...]. Tags: Left=0, Right=1,
--   UnderflowError=0. Returns `Left UnderflowError` on INT32_MIN,
--   `Right (v - 1)` otherwise.
rtPredI32 :: Text
rtPredI32 =
  unlines
    [ "  (func $__predInt32 (param $p i32) (result i32)",
      "    (local $v i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eq (local.get $v) (i32.const -2147483648))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

rtGetArg :: Int -> Text
rtGetArg emptyOff =
  unlines
    [ "  (func $__get_arg (result i32)",
      "    (local $argv_buf i32) (local $ptrs i32)",
      "    (drop (call $args_sizes_get (i32.const 12) (i32.const 16)))",
      "    (if (result i32) (i32.lt_u (i32.load (i32.const 12)) (i32.const 2))",
      "      (then (i32.const " <> show emptyOff <> "))",
      "      (else",
      "        (local.set $argv_buf (call $__alloc (i32.load (i32.const 16))))",
      "        (local.set $ptrs (call $__alloc (i32.mul (i32.load (i32.const 12)) (i32.const 4))))",
      "        (drop (call $args_get (local.get $ptrs) (local.get $argv_buf)))",
      "        (i32.load (i32.add (local.get $ptrs) (i32.const 4))))))"
    ]

startFunc :: Text
startFunc =
  unlines
    [ "  (func $_start (export \"_start\")",
      "    (drop (call $" <> mangle "main" <> " (call $__get_arg))))"
    ]

-- ════════════════════════════════════════════════════════════════════════════
-- User declarations
-- ════════════════════════════════════════════════════════════════════════════

emitDecl :: WasmCtx -> CDecl -> Text
emitDecl ctx = \case
  CFunDef nm args body ->
    let paramSet = Set.fromList args
        localCtx = ctx {wParams = paramSet, wLocalExprs = Map.empty}
        wasmParams = T.intercalate " " (map (\a -> "(param $" <> mangle a <> " i32)") args)
        locals = collectLocals body
     in "  (func $"
          <> mangle nm
          <> " (export \""
          <> mangle nm
          <> "\") "
          <> wasmParams
          <> " (result i32)"
          <> locals
          <> "\n    "
          <> emitExpr localCtx body
          <> ")"
  CValDef nm rhs ->
    let localCtx = ctx {wParams = Set.empty, wLocalExprs = Map.empty}
        locals = collectLocals rhs
     in "  (func $"
          <> mangle nm
          <> " (export \""
          <> mangle nm
          <> "\") (result i32)"
          <> locals
          <> "\n    "
          <> emitExpr localCtx rhs
          <> ")"

-- ════════════════════════════════════════════════════════════════════════════
-- Expressions
-- ════════════════════════════════════════════════════════════════════════════

emitExpr :: WasmCtx -> CExpr -> Text
emitExpr ctx = \case
  CString s ->
    let offset = fromMaybe (error $ "string not in pool: " <> show s) (Map.lookup s ctx.wStringPool)
     in "(i32.const " <> show offset <> ")"
  CVar n
    | Just expr <- Map.lookup n ctx.wLocalExprs -> expr
    | n `Set.member` ctx.wParams ->
        "(local.get $" <> mangle n <> ")"
    | n `Set.member` ctx.wValDefs ->
        "(call $" <> mangle n <> ")"
    | n `Set.member` ctx.wFunDefs ->
        let idx = fromMaybe 0 (Map.lookup n ctx.wTableMap)
         in "(i32.const " <> show idx <> ")"
    | otherwise ->
        "(i32.const 0)"
  CPrim _ ->
    "(i32.const 0)"
  CBuiltIn _ ->
    "(i32.const 0)" -- invariant: not a standalone term; dispatched from CCall
  CIntLit n _ ->
    let n32 = fromInteger n :: Int32
     in "(call $__box_i32 (i32.const " <> show n32 <> "))"
  CCon tag fields ->
    let conLocal = "$__con_" <> show ctx.wConDepth
        nestedCtx = ctx {wConDepth = ctx.wConDepth + 1}
        nSlots = 1 + length fields
        storeTag = "(i32.store (local.tee " <> conLocal <> " (call $__alloc (i32.const " <> show (nSlots * 4 :: Int) <> "))) (i32.const " <> show tag <> "))"
        storeFields =
          [ "(i32.store offset=" <> show (i * 4 :: Int) <> " (local.get " <> conLocal <> ") " <> emitExpr nestedCtx fld <> ")"
          | (fld, i) <- zip fields [1 :: Int ..]
          ]
     in "(block (result i32) " <> T.intercalate " " (storeTag : storeFields <> ["(local.get " <> conLocal <> ")"]) <> ")"
  CCase scrut alts ->
    emitCaseExpr ctx scrut alts
  CCall f xs ->
    case f of
      CPrim PrimConcat
        | [a, b] <- xs ->
            "(call $__concat " <> emitExpr ctx a <> " " <> emitExpr ctx b <> ")"
      CPrim PrimPrint
        | [x] <- xs ->
            "(call $__print " <> emitExpr ctx x <> ")"
      CPrim (PrimShowInt _)
        | [x] <- xs ->
            "(call $__show_i32 " <> emitExpr ctx x <> ")"
      CBuiltIn name
        | name == "showInt32" || name == "showUInt8",
          [x] <- xs ->
            "(call $__show_i32 " <> emitExpr ctx x <> ")"
      CBuiltIn "predInt32"
        | [x] <- xs ->
            "(call $__predInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn n ->
        error ("WASM codegen: unknown builtin '" <> n <> "' reached CCall (typecheck should have rejected it)")
      CVar n
        | n `Set.member` ctx.wFunDefs ->
            "(call $" <> mangle n <> " " <> T.intercalate " " (map (emitExpr ctx) xs) <> ")"
      _ ->
        let arity = length xs
         in "(call_indirect (type $arity_"
              <> show arity
              <> ") "
              <> T.intercalate " " (map (emitExpr ctx) xs)
              <> " "
              <> emitExpr ctx f
              <> ")"

-- | Emit a case expression as nested @if\/else@ in WAT.
--   Stores the scrutinee in @$__scrut@, extracts the tag from offset 0,
--   and binds field values via inline @i32.load offset=N@ expressions.
emitCaseExpr :: WasmCtx -> CExpr -> [(Int, [Text], CExpr)] -> Text
emitCaseExpr ctx scrut alts =
  let sorted = sortWith (\(t, _, _) -> t) alts
      scrutCode = emitExpr ctx scrut
   in "(block (result i32) (local.set $__scrut " <> scrutCode <> ") " <> buildChain sorted <> ")"
  where
    bindVars vars =
      let entries = [(v, "(i32.load offset=" <> show (i * 4 :: Int) <> " (local.get $__scrut))") | (v, i) <- zip vars [1 :: Int ..]]
       in ctx {wLocalExprs = foldl' (\m (k, e) -> Map.insert k e m) ctx.wLocalExprs entries}
    buildChain [] = "(unreachable)"
    buildChain [(_, vars, body)] = emitExpr (bindVars vars) body
    buildChain ((tag, vars, body) : rest) =
      "(if (result i32) (i32.eq (i32.load (local.get $__scrut)) (i32.const "
        <> show tag
        <> ")) (then "
        <> emitExpr (bindVars vars) body
        <> ") (else "
        <> buildChain rest
        <> "))"

-- | Determine which locals a function body needs and emit their declarations.
collectLocals :: CExpr -> Text
collectLocals body =
  let depth = maxConDepth body
      conLocals = T.concat ["\n    (local $__con_" <> show i <> " i32)" | i <- [0 .. depth - 1]]
      ns = hasCCase body
   in conLocals
        <> (if ns then "\n    (local $__scrut i32)" else "")

-- | Compute the maximum CCon nesting depth in an expression.
maxConDepth :: CExpr -> Int
maxConDepth = \case
  CCon _ fields -> 1 + foldl' max 0 (map maxConDepth fields)
  CCase s alts -> max (maxConDepth s) (foldl' max 0 [maxConDepth b | (_, _, b) <- alts])
  CCall f xs -> foldl' max (maxConDepth f) (map maxConDepth xs)
  _ -> 0

hasCCase :: CExpr -> Bool
hasCCase = \case
  CCase {} -> True
  CCall f xs -> hasCCase f || any hasCCase xs
  _ -> False

-- ════════════════════════════════════════════════════════════════════════════
-- Name mangling
-- ════════════════════════════════════════════════════════════════════════════

-- | All names get @v_@ prefix (including @main@ → @v_main@),
--   because @_start@ is the WASI entry point.
mangle :: Text -> Text
mangle t =
  let ok c = Char.isAlphaNum c || c == '_' || c == '\''
      body = T.map (\c -> if ok c then c else '_') t
   in "v_" <> body
